  v_found text[];
begin
  -- 1. Exactly the listed objects, no more and no fewer.
  v_problems := v_problems || coalesce((
    select array_agg('table not expected: ' || a.name order by a.name)
      from (select c.relname::text as name from pg_catalog.pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind in ('r', 'p')) a
     where not (a.name = any (v_tables))), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('table missing: ' || e.name order by e.name)
      from unnest(v_tables) e(name)
     where not exists (select 1 from (select c.relname::text as name from pg_catalog.pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind in ('r', 'p')) a where a.name = e.name)), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('view not expected: ' || a.name order by a.name)
      from (select c.relname::text as name from pg_catalog.pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind in ('v', 'm')) a
     where not (a.name = any (v_views))), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('view missing: ' || e.name order by e.name)
      from unnest(v_views) e(name)
     where not exists (select 1 from (select c.relname::text as name from pg_catalog.pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind in ('v', 'm')) a where a.name = e.name)), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('function not expected: ' || a.name order by a.name)
      from (select f.name from (select p.proname::text as name, p.oid, p.proacl
        from pg_catalog.pg_proc p
       where p.pronamespace = 'public'::regnamespace
         and not exists (select 1 from pg_catalog.pg_depend d where d.objid = p.oid and d.deptype = 'e')) f) a
     where not (a.name = any (v_functions))), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('function missing: ' || e.name order by e.name)
      from unnest(v_functions) e(name)
     where not exists (select 1 from (select f.name from (select p.proname::text as name, p.oid, p.proacl
        from pg_catalog.pg_proc p
       where p.pronamespace = 'public'::regnamespace
         and not exists (select 1 from pg_catalog.pg_depend d where d.objid = p.oid and d.deptype = 'e')) f) a where a.name = e.name)), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('trigger not expected: ' || a.name order by a.name)
      from (select (case when n.nspname = 'public' then '' else n.nspname::text || '.' end) || c.relname::text || '.' || t.tgname::text as name
        from pg_catalog.pg_trigger t
        join pg_catalog.pg_class c on c.oid = t.tgrelid
        join pg_catalog.pg_namespace n on n.oid = c.relnamespace
        join pg_catalog.pg_proc p on p.oid = t.tgfoid
       where not t.tgisinternal and (n.nspname = 'public' or p.pronamespace = 'public'::regnamespace)) a
     where not (a.name = any (v_triggers))), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('trigger missing: ' || e.name order by e.name)
      from unnest(v_triggers) e(name)
     where not exists (select 1 from (select (case when n.nspname = 'public' then '' else n.nspname::text || '.' end) || c.relname::text || '.' || t.tgname::text as name
        from pg_catalog.pg_trigger t
        join pg_catalog.pg_class c on c.oid = t.tgrelid
        join pg_catalog.pg_namespace n on n.oid = c.relnamespace
        join pg_catalog.pg_proc p on p.oid = t.tgfoid
       where not t.tgisinternal and (n.nspname = 'public' or p.pronamespace = 'public'::regnamespace)) a where a.name = e.name)), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('private function not expected: ' || a.name order by a.name)
      from (select p.proname::text as name from pg_catalog.pg_proc p where p.pronamespace = 'engine'::regnamespace) a
     where not (a.name = any (v_private_functions))), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('private function missing: ' || e.name order by e.name)
      from unnest(v_private_functions) e(name)
     where not exists (select 1 from (select p.proname::text as name from pg_catalog.pg_proc p where p.pronamespace = 'engine'::regnamespace) a where a.name = e.name)), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('private table not expected: ' || a.name order by a.name)
      from (select c.relname::text as name from pg_catalog.pg_class c where c.relnamespace = 'engine'::regnamespace and c.relkind = 'r') a
     where not (a.name = any (v_private_tables))), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('private table missing: ' || e.name order by e.name)
      from unnest(v_private_tables) e(name)
     where not exists (select 1 from (select c.relname::text as name from pg_catalog.pg_class c where c.relnamespace = 'engine'::regnamespace and c.relkind = 'r') a where a.name = e.name)), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('migration not expected: ' || a.name order by a.name)
      from (select m.version as name from engine.schema_migrations m) a
     where not (a.name = any (v_versions))), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('migration missing: ' || e.name order by e.name)
      from unnest(v_versions) e(name)
     where not exists (select 1 from (select m.version as name from engine.schema_migrations m) a where a.name = e.name)), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('storage bucket not expected: ' || a.name order by a.name)
      from (select b.id::text as name from storage.buckets b) a
     where not (a.name = any (v_buckets))), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('storage bucket missing: ' || e.name order by e.name)
      from unnest(v_buckets) e(name)
     where not exists (select 1 from (select b.id::text as name from storage.buckets b) a where a.name = e.name)), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('realtime table not expected: ' || a.name order by a.name)
      from (select p.tablename::text as name from pg_catalog.pg_publication_tables p where p.pubname = 'supabase_realtime' and p.schemaname = 'public') a
     where not (a.name = any (v_realtime))), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('realtime table missing: ' || e.name order by e.name)
      from unnest(v_realtime) e(name)
     where not exists (select 1 from (select p.tablename::text as name from pg_catalog.pg_publication_tables p where p.pubname = 'supabase_realtime' and p.schemaname = 'public') a where a.name = e.name)), array[]::text[]);

  -- 2. Who can call what: the signed-out role, and everyone.
  v_problems := v_problems || coalesce((
    select array_agg('function the signed-out role can call not expected: ' || a.name order by a.name)
      from (select f.name from (select p.proname::text as name, p.oid, p.proacl
        from pg_catalog.pg_proc p
       where p.pronamespace = 'public'::regnamespace
         and not exists (select 1 from pg_catalog.pg_depend d where d.objid = p.oid and d.deptype = 'e')) f where pg_catalog.has_function_privilege('anon', f.oid, 'execute')) a
     where not (a.name = any (v_anon))), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('function the signed-out role can call missing: ' || e.name order by e.name)
      from unnest(v_anon) e(name)
     where not exists (select 1 from (select f.name from (select p.proname::text as name, p.oid, p.proacl
        from pg_catalog.pg_proc p
       where p.pronamespace = 'public'::regnamespace
         and not exists (select 1 from pg_catalog.pg_depend d where d.objid = p.oid and d.deptype = 'e')) f where pg_catalog.has_function_privilege('anon', f.oid, 'execute')) a where a.name = e.name)), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('function open to every role not expected: ' || a.name order by a.name)
      from (select f.name from (select p.proname::text as name, p.oid, p.proacl
        from pg_catalog.pg_proc p
       where p.pronamespace = 'public'::regnamespace
         and not exists (select 1 from pg_catalog.pg_depend d where d.objid = p.oid and d.deptype = 'e')) f where exists (select 1 from pg_catalog.aclexplode(f.proacl) g where g.grantee = 0)) a
     where not (a.name = any (v_public))), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('function open to every role missing: ' || e.name order by e.name)
      from unnest(v_public) e(name)
     where not exists (select 1 from (select f.name from (select p.proname::text as name, p.oid, p.proacl
        from pg_catalog.pg_proc p
       where p.pronamespace = 'public'::regnamespace
         and not exists (select 1 from pg_catalog.pg_depend d where d.objid = p.oid and d.deptype = 'e')) f where exists (select 1 from pg_catalog.aclexplode(f.proacl) g where g.grantee = 0)) a where a.name = e.name)), array[]::text[]);

  -- 3. Scheduled jobs, where the scheduler exists.
  if pg_catalog.to_regclass('cron.job') is not null then
    execute 'select array_agg(j.jobname::text) from cron.job j' into v_found;
    v_problems := v_problems || coalesce((
      select array_agg('scheduled job not expected: ' || f.name order by f.name)
        from unnest(coalesce(v_found, array[]::text[])) f(name) where not (f.name = any (v_jobs))), array[]::text[]);
    v_problems := v_problems || coalesce((
      select array_agg('scheduled job missing: ' || e.name order by e.name)
        from unnest(v_jobs) e(name) where not (e.name = any (coalesce(v_found, array[]::text[])))), array[]::text[]);
  else
    v_problems := v_problems || array['the job scheduler is missing']::text[];
  end if;

  -- 4. Nothing that stays out of every tenant.
  v_problems := v_problems || coalesce((
    select array_agg('a schema that stays out exists: ' || n.nspname::text order by n.nspname)
      from pg_catalog.pg_namespace n where n.nspname::text = any (v_denied_schemas)), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('a name that stays out exists: ' || x.kind || ' ' || x.name order by x.kind, x.name)
      from (
        select 'relation' as kind, c.relname::text as name
          from pg_catalog.pg_class c where c.relnamespace in ('public'::regnamespace, 'engine'::regnamespace)
        union all
        select 'function', p.proname::text
          from pg_catalog.pg_proc p where p.pronamespace in ('public'::regnamespace, 'engine'::regnamespace)
        union all
        select 'trigger', t.tgname::text from pg_catalog.pg_trigger t where not t.tgisinternal
        union all
        select 'column', a.attname::text
          from pg_catalog.pg_attribute a
          join pg_catalog.pg_class c on c.oid = a.attrelid
         where c.relnamespace = 'public'::regnamespace and a.attnum > 0 and not a.attisdropped
        union all
        select 'storage bucket', b.id::text from storage.buckets b
      ) x
     where x.name = any (v_denied)), array[]::text[]);
  v_problems := v_problems || coalesce((
    select array_agg('a column that stays out exists: ' || c.relname::text || '.' || a.attname::text)
      from pg_catalog.pg_attribute a
      join pg_catalog.pg_class c on c.oid = a.attrelid
     where c.relnamespace = 'public'::regnamespace and a.attnum > 0 and not a.attisdropped
       and (c.relname::text || '.' || a.attname::text) = any (v_denied_columns)), array[]::text[]);

  if pg_catalog.array_length(v_problems, 1) > 0 then
    raise exception 'CATALOGUE CHECK FAILED (% problems): %',
      pg_catalog.array_length(v_problems, 1), pg_catalog.array_to_string(v_problems, '; ');
  end if;
end;
$catalogue$;
